const subtreeLocked = `-- name: SubtreeLocked :one
WITH RECURSIVE up (id, parent_id) AS (
    SELECT t.id, t.parent_id FROM task t WHERE t.id = ?1
    UNION ALL
    SELECT t.id, t.parent_id FROM task t JOIN up ON t.id = up.parent_id
), down (id) AS (
    SELECT t.id FROM task t WHERE t.parent_id = ?1
    UNION ALL
    SELECT t.id FROM task t JOIN down ON t.parent_id = down.id
), near (id) AS (
    SELECT id FROM up UNION SELECT id FROM down
)
SELECT CAST(COUNT(*) > 0 AS INTEGER) AS locked
FROM run r JOIN near ON near.id = r.task_id
WHERE r.state NOT IN ('succeeded', 'failed', 'blocked', 'cancelled')
`

// 1 if an active run's root is an ancestor-or-self or a descendant of root_id.
func (q *Queries) SubtreeLocked(ctx context.Context, rootID int64) (int64, error) {
	row := q.db.QueryRowContext(ctx, subtreeLocked, rootID)
	var locked int64
	err := row.Scan(&locked)
	return locked, err
}

const subtreeOrdered = `-- name: SubtreeOrdered :many
WITH RECURSIVE sub (id, depth, path) AS (
    SELECT t.id, 0, t.rank FROM task t WHERE t.id = ?1
    UNION ALL
    SELECT c.id, sub.depth + 1, sub.path || ' ' || c.rank
    FROM task c JOIN sub ON c.parent_id = sub.id
)
SELECT task.id, task.sqid, task.parent_id, task.title, task.state, task.rank,
       CAST(sub.depth AS INTEGER) AS depth, CAST(sub.path AS TEXT) AS path
FROM sub JOIN task ON task.id = sub.id
ORDER BY sub.path
`

type SubtreeOrderedRow struct {
	ID       int64          `json:"id"`
	Sqid     sql.NullString `json:"sqid"`
	ParentID sql.NullInt64  `json:"parent_id"`
	Title    string         `json:"title"`
	State    string         `json:"state"`
	Rank     string         `json:"rank"`
	Depth    int64          `json:"depth"`
	Path     string         `json:"path"`
}

// Every task under (and including) root, depth-first in rank order.
func (q *Queries) SubtreeOrdered(ctx context.Context, rootID int64) ([]SubtreeOrderedRow, error) {
	rows, err := q.db.QueryContext(ctx, subtreeOrdered, rootID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SubtreeOrderedRow{}
	for rows.Next() {
		var i SubtreeOrderedRow
		if err := rows.Scan(
			&i.ID,
			&i.Sqid,
			&i.ParentID,
			&i.Title,
			&i.State,
			&i.Rank,
			&i.Depth,
			&i.Path,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const subtreeRepoIDs = `-- name: SubtreeRepoIDs :many
WITH RECURSIVE sub (id) AS (
    SELECT t.id FROM task t WHERE t.id = ?1
    UNION ALL
    SELECT c.id FROM task c JOIN sub ON c.parent_id = sub.id
)
SELECT DISTINCT CAST(task.repo_id AS INTEGER) AS repo_id FROM sub JOIN task ON task.id = sub.id
WHERE task.repo_id IS NOT NULL
`

// Distinct explicit repo ids anywhere in the subtree.
func (q *Queries) SubtreeRepoIDs(ctx context.Context, rootID int64) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, subtreeRepoIDs, rootID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var repo_id int64
		if err := rows.Scan(&repo_id); err != nil {
			return nil, err
		}
		items = append(items, repo_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

